    static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(var item in Walk(child))yield return item;}
    static bool Reject(Action a){try{a();return false;}catch(Exception e)when(e is ArgumentException or IOException or InvalidOperationException){return true;}}
    public static void Run(string report){Directory.CreateDirectory(Path.GetDirectoryName(report)!);using var ui=new Form{Opacity=0,ShowInTaskbar=false};ui.Shown+=async(_,_)=>{var checks=new Dictionary<string,bool>();try{await Check(Path.GetDirectoryName(report)!,checks);File.WriteAllText(report,JsonSerializer.Serialize(new{ok=checks.Values.All(x=>x),checks,personal_data_reads=0,network_requests=0,third_party_modules_started=0},new JsonSerializerOptions{WriteIndented=true}));}catch(Exception e){File.WriteAllText(report,JsonSerializer.Serialize(new{ok=false,error=e.ToString(),checks}));}finally{ui.Close();}};Application.Run(ui);}
    static async Task Check(string directory,Dictionary<string,bool> c)
    {
        string root=Path.Combine(directory,"packages-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var prefs=new Preferences{ApplicationIndexing=false};var store=new ExtensionStore(Path.Combine(root,"modules")){Preferences=prefs};
        var legacy=new ExtensionManifest("LeoModule/1","fixture-plan","隔离声明","1.0.0",[new("open","打开隔离清单",[],"todos_open")]);
        string json=Path.Combine(root,"legacy.json");File.WriteAllText(json,"{\"Format\":\"LeoModule/1\",\"Id\":\"fixture-plan\",\"Name\":\"legacy\",\"Version\":\"1.0.0\",\"Commands\":[{\"Id\":\"open\",\"Title\":\"open\",\"Phrases\":[],\"Action\":\"todos_open\"}]}");
        var old=store.Inspect(json);store.Install(old);c["omitted_fields_legacy_import"]=old.HostMin==null&&old.Dependencies==null&&store.Load().Length==1;
        c["inclusive_normalized_host_range"]=ExtensionCompatibility.Read(legacy with{HostMin="1.4.0",HostMax="1.4.0"},store,new Version(1,4,0,0)).Compatible;
        c["host_below_and_above_rejected"]=!ExtensionCompatibility.Read(legacy with{HostMin="2.0"},store,new Version(1,0)).Compatible&&!ExtensionCompatibility.Read(legacy with{HostMax="1.0"},store,new Version(2,0)).Compatible;
        c["invalid_ranges_rejected"]=Reject(()=>store.Install(legacy with{HostMin="nonsense"}))&&Reject(()=>store.Install(legacy with{HostMin="2.0",HostMax="1.0"}));
        c["invalid_dependency_metadata_rejected"]=Reject(()=>store.Install(legacy with{Dependencies=["windows","windows"]}))&&Reject(()=>store.Install(legacy with{Dependencies=["../path"] ,HostMin="invalid"}))&&Reject(()=>store.Install(legacy with{Dependencies=["bad dependency"]}));
        c["known_passive_dependencies"]=ExtensionCompatibility.Read(legacy with{Dependencies=["windows","leo-module/1","leo-host-contract/1","stdio/v1"]},store).Compatible;
        string current=Path.Combine(store.Root,legacy.Id,"module.json"),original=File.ReadAllText(current);c["unknown_and_missing_reject_before_write"]=Reject(()=>store.Install(legacy with{Version="1.1.0",Dependencies=["not-supported"]}))&&Reject(()=>store.Install(legacy with{Version="1.1.0",Dependencies=["module:absent"]}))&&File.ReadAllText(current)==original;
        var dependency=legacy with{Id="fixture-dependency"};store.Install(dependency);var dependent=legacy with{Id="fixture-dependent",Dependencies=["module:fixture-dependency"]};store.Install(dependent);c["installed_dependency_available"]=ExtensionCompatibility.Read(dependent,store).Compatible;
        prefs.DisabledExtensions.Add(dependency.Id);c["disabled_dependency_unavailable"]=!ExtensionCompatibility.Read(dependent,store).Compatible;prefs.DisabledExtensions.Clear();
        File.WriteAllText(Path.Combine(store.Root,dependency.Id,"module.json"),JsonSerializer.Serialize(dependency with{HostMin="999.0"}));c["incompatible_transitive_dependency_unavailable"]=!ExtensionCompatibility.Read(dependent,store).Compatible;
        File.WriteAllText(Path.Combine(store.Root,dependency.Id,"module.json"),JsonSerializer.Serialize(dependency with{Dependencies=["module:fixture-dependent"]}));c["dependency_cycle_unavailable"]=!ExtensionCompatibility.Read(dependent,store).Compatible;
        File.WriteAllText(Path.Combine(store.Root,dependency.Id,"module.json"),JsonSerializer.Serialize(dependency));
        AtomicJson.BeforeReplace=p=>{if(p==current)throw new IOException("isolated save failure");};try{c["json_update_failure_retains_original"]=Reject(()=>store.Install(legacy with{Version="1.1.0"}))&&File.ReadAllText(current)==original;}finally{AtomicJson.BeforeReplace=null;}
        string worker=Path.Combine(directory,"worker.exe");if(!File.Exists(worker))throw new IOException("repository worker fixture missing");var manifest=legacy with{Id="fixture-worker",Runtime="stdio",Executable="worker.exe",Commands=[new("hello","隔离响应",[],"worker:hello")]};
        string Package(ExtensionManifest m,bool includeWorker=true){string zip=Path.Combine(root,Guid.NewGuid().ToString("N")+".zip");using var archive=ZipFile.Open(zip,ZipArchiveMode.Create);using(var writer=new StreamWriter(archive.CreateEntry("module.json").Open()))writer.Write(JsonSerializer.Serialize(m));if(includeWorker)archive.CreateEntryFromFile(worker,"worker.exe");return zip;}
        string v1=Package(manifest),v2=Package(manifest with{Version="1.1.0"});store.InstallPackage(v1);string folder=Path.Combine(store.Root,manifest.Id);byte[] binary=File.ReadAllBytes(Path.Combine(folder,"worker.exe"));string first=File.ReadAllText(Path.Combine(folder,"module.json"));
        string data=Path.Combine(root,"module-data",manifest.Id,"keep.txt");Directory.CreateDirectory(Path.GetDirectoryName(data)!);File.WriteAllText(data,"isolated durable data");prefs.EntryDisplayModes["ext:fixture-worker/hello"]=EntryDisplay.Menu;prefs.DisabledExtensions.Add(manifest.Id);string preferences=JsonSerializer.Serialize(prefs);
        foreach(string step in new[]{"prepared","promote"}){store.BeforeInstallStep=s=>{if(s==step)throw new IOException("isolated "+step);};c[step+"_failure_restores_old_package"]=Reject(()=>store.InstallPackage(v2))&&File.ReadAllText(Path.Combine(folder,"module.json"))==first&&File.ReadAllBytes(Path.Combine(folder,"worker.exe")).SequenceEqual(binary)&&!Directory.GetDirectories(store.Root,".install-*").Any();}
        store.BeforeInstallStep=null;
        store.BeforeInstallStep=s=>{if(s is "promote" or "restore")throw new IOException("isolated recovery failure");};string? recoveryMessage=null;try{store.InstallPackage(v2);}catch(IOException e){recoveryMessage=e.Message;}finally{store.BeforeInstallStep=null;}var retained=Directory.GetDirectories(store.Root,".previous-*").Single();c["restore_failure_reports_retained_old_package"]=recoveryMessage?.Contains("自动恢复未完成")==true&&!Directory.Exists(folder)&&File.ReadAllText(Path.Combine(retained,"module.json"))==first;Directory.Move(retained,folder);
        c["package_failure_retains_configuration_and_module_data"]=JsonSerializer.Serialize(prefs)==preferences&&File.ReadAllText(data)=="isolated durable data";
        c["incompatible_zip_rejected_before_replacement"]=Reject(()=>store.InstallPackage(Package(manifest with{Version="1.1.0",HostMin="999.0"})))&&File.ReadAllText(Path.Combine(folder,"module.json"))==first;
        c["missing_worker_rejected_before_replacement"]=Reject(()=>store.InstallPackage(Package(manifest with{Version="1.1.0"},false)))&&File.ReadAllText(Path.Combine(folder,"module.json"))==first;
        store.BeforeInstallStep=s=>{if(s=="cleanup")throw new IOException("isolated cleanup failure");};store.InstallPackage(v2);store.BeforeInstallStep=null;c["cleanup_failure_reports_success_with_retained_backup"]=store.Load().Single(m=>m.Id==manifest.Id).Version=="1.1.0"&&store.LastWarning!=null&&Directory.GetDirectories(store.Root,".previous-*").Length==1;
        c["successful_update_preserves_data_and_preferences"]=JsonSerializer.Serialize(prefs)==preferences&&File.ReadAllText(data)=="isolated durable data";
        var fresh=manifest with{Id="fixture-fresh"};store.BeforeInstallStep=s=>{if(s=="promote")throw new IOException("isolated fresh failure");};c["first_install_failure_leaves_no_active_package"]=Reject(()=>store.InstallPackage(Package(fresh)))&&!Directory.Exists(Path.Combine(store.Root,fresh.Id));store.BeforeInstallStep=null;
        prefs.DisabledExtensions.Clear();using var bus=new ActionDispatcher(prefs,(_,_,_)=>Task.FromResult("unused"),store);var result=await bus.ExecuteDetailedAsync(new("ext:fixture-worker:hello"));c["repository_worker_still_runs_after_recovery"]=result.Status=="succeeded"&&!ModuleWorker.Running(manifest.Id);
        File.WriteAllText(Path.Combine(folder,"module.json"),JsonSerializer.Serialize(manifest with{Version="1.1.0",HostMin="999.0",Dependencies=["not-supported"]}));c["manually_installed_incompatible_visible_but_not_executable"]=store.Load().Any(m=>m.Id==manifest.Id)&&!bus.Registry.Resolve("ext:fixture-worker:hello").Enabled&&(await bus.ExecuteDetailedAsync(new("ext:fixture-worker:hello"))).Status!="succeeded";
        using(var manager=new ExtensionManager(prefs,true,store)){manager.Show();manager.Location=new(-19000,-19000);var list=Walk(manager).OfType<ListBox>().Single();list.SelectedIndex=Array.FindIndex(store.Load(),m=>m.Id==manifest.Id);var text=Walk(manager).OfType<TextBox>().Single().Text;c["existing_manager_displays_compatibility_and_dependencies"]=list.SelectedItem!.ToString()!.StartsWith("不可用")&&text.Contains("宿主范围")&&text.Contains("999.0")&&text.Contains("not-supported");manager.Close();}
        c["other_legacy_extension_remains_enabled"]=bus.Registry.Resolve("ext:fixture-plan:open").Enabled;
        c["no_worker_left_running"]=!ModuleWorker.Running(manifest.Id);
        store.Remove(manifest.Id);c["removal_preserves_module_data"]=!Directory.Exists(folder)&&File.ReadAllText(data)=="isolated durable data";
    }
